-- 0053: تعميق الأدلة (المرحلة 1): طبقة توثيق كاملة لكل إجراء (doc) وتفاصيل اختيارية لكل خطوة
-- (detail[] / criteria / escalate / record). يُملأ المحتوى لستة إجراءات نموذجية مرة واحدة فقط إذا كان doc فارغاً،
-- ويُدمج إثراء الخطوات مع الخطوات الحالية دون استبدالها، فلا تُمس أي تعديلات أجراها المسؤول.
alter table public.gov_processes add column if not exists doc jsonb not null default '{}'::jsonb;

update public.gov_processes p set
  doc = '{"purpose": "ضمان ألا يُنفَّذ أي عمل عالي الخطورة في منشآت التجمع إلا بتصريح مكتوب يحدد المخاطر وضوابطها والمسؤول عنها، مع عزل آمن ومُتحقَّق منه لمصادر الطاقة (كهرباء، ضغط، غازات، حركة) قبل البدء وحتى إعادة التشغيل.", "scope": "جميع الأعمال المذكورة في القاعدة R-13 داخل المنشآت ومبانيها الملحقة وأسطحها، سواء نفذها فريق الصيانة أو مقاولو التشغيل أو مقاولو المشاريع أو موردو الأجهزة: الأعمال الساخنة، والعزل الكهربائي والميكانيكي (LOTO)، والأماكن المحصورة، والعمل على ارتفاع أكثر من 1.8 م، وفتح الأسقف في مناطق المرضى، والعمل على الأسطح والواجهات، وأي عمل يتطلب تعطيل نظام سلامة.", "out_of_scope": "الأعمال الروتينية منخفضة الخطورة (تغيير مصباح، شد مسمار، تنظيف) التي لا تتطلب عزل طاقة ولا تولّد حرارة أو غباراً في منطقة مرضى.", "definitions": [{"t": "تصريح العمل", "d": "وثيقة مكتوبة صالحة لوردية واحدة تأذن بعمل محدد في موقع ووقت محددين بضوابط محددة."}, {"t": "مُصدر التصاريح", "d": "مهندس أو مشرف صيانة مسمّى خطياً من رئيس قسم الصيانة ومدرّب على تقييم المخاطر."}, {"t": "العزل الآمن (LOTO)", "d": "قطع مصدر الطاقة وقفله بقفل شخصي وبطاقة باسم واضعه، ثم التحقق من انعدام الطاقة المتبقية قبل لمس المعدة."}, {"t": "العمل الساخن", "d": "أي عمل يولّد لهباً أو شرراً أو حرارة كافية للإشعال: لحام، قطع، تجليخ، لحام بالقصدير، استخدام اللهب المكشوف."}, {"t": "مراقب الحريق", "d": "شخص مدرّب ومعه طفاية مناسبة، مهمته الوحيدة مراقبة موقع العمل الساخن أثناءه وبعده."}], "roles": [{"role": "رئيس قسم الصيانة", "resp": "مالك الإجراء؛ يسمّي مُصدري التصاريح، ويعتمد أي إزالة استثنائية لبطاقة عزل، ويراجع سجل التصاريح شهرياً."}, {"role": "مُصدر التصاريح", "resp": "يراجع الطلب وتقييم المخاطر، ويحدد الضوابط، ويُصدر التصريح ويغلقه، ويتحقق من العزل."}, {"role": "الأمن والسلامة", "resp": "يعتمد التصاريح عالية الخطورة، ويفتش مواقعها، ويملك صلاحية إيقاف العمل فوراً."}, {"role": "مكافحة العدوى (المنشأة)", "resp": "تقيّم مخاطر العدوى (ICRA) للأعمال في المناطق المشغّلة وتحدد فئة الحماية."}, {"role": "المنفّذ (الفريق أو المقاول)", "resp": "يطلب التصريح، ويلتزم بضوابطه، ويُبقيه معلقاً في الموقع، ويوقّع على الإغلاق."}, {"role": "مهندس المشروع", "resp": "ينسق تصاريح مقاولي المشاريع مع مُصدر التصاريح ويتابع التزامهم."}], "refs": [{"std": "سباهي — معايير المنشآت الصحية، فصل إدارة المرافق والسلامة (FMS)", "title": "تصاريح العمل، سلامة المقاولين، والمخاطر أثناء الإنشاء والتجديد"}, {"std": "NFPA 51B", "title": "الوقاية من الحريق أثناء اللحام والقطع والأعمال الساخنة"}, {"std": "OSHA 29 CFR 1910.147", "title": "التحكم في الطاقة الخطرة (القفل والبطاقة)"}, {"std": "NFPA 70E", "title": "السلامة الكهربائية في أماكن العمل"}, {"std": "ASHE ICRA 2.0", "title": "تقييم مخاطر العدوى أثناء الإنشاء والتجديد"}, {"std": "SBC 801", "title": "كود الحماية من الحريق السعودي — الأعمال الساخنة"}], "risks": [{"risk": "حريق من شرر أعمال ساخنة قرب مواد قابلة للاشتعال", "control": "إزالة أو تغطية المواد ضمن 11 م، طفاية مناسبة، مراقب حريق أثناء العمل و30 دقيقة بعده، عزل كواشف المنطقة فقط بتعطيل مسجل (H-01)."}, {"risk": "صعق كهربائي أو تشغيل معدة أثناء العمل", "control": "عزل بقفل شخصي لكل عامل، والتحقق بجهاز قياس من انعدام الجهد، ومنع الإزالة إلا من واضع القفل."}, {"risk": "اختناق في مكان محصور", "control": "قياس الغازات قبل الدخول وأثناءه، تهوية قسرية، مراقب خارجي، خطة إنقاذ."}, {"risk": "سقوط من ارتفاع", "control": "سقالات معتمدة أو منصات آلية بشهادة فحص، أحزمة أمان مربوطة بنقاط تثبيت."}, {"risk": "انتشار غبار ملوث لمنطقة مرضى", "control": "حواجز ICRA حسب الفئة، ضغط سالب، ممسحات لاصقة عند المدخل، العمل خارج أوقات الذروة."}], "exceptions": [{"case": "عطل طارئ خارج الدوام يتطلب عملاً عالي الخطورة", "action": "يُصدر المشرف المناوب التصريح هاتفياً ويوثقه فوراً في المنصة، ويُبلَّغ الأمن والسلامة، ويُراجع صباح اليوم التالي."}, {"case": "عمل يمتد لأكثر من وردية", "action": "يُجدَّد التصريح في بداية كل وردية بعد التحقق من استمرار صلاحية الضوابط."}, {"case": "غياب واضع قفل العزل", "action": "لا يُزال القفل إلا بإجراء موثق: التحقق من خلو الموقع، محاولة الاتصال بصاحبه، اعتماد رئيس قسم الصيانة، وتسجيل الواقعة."}], "records": [{"name": "تصريح العمل الموقّع (نموذج «تصريح عمل» في المنصة)", "where": "البلاغات والطلبات ← تصريح عمل", "keep": "5 سنوات"}, {"name": "سجل العزل والأقفال", "where": "مرفق التصريح", "keep": "5 سنوات"}, {"name": "تقييم ICRA", "where": "مرفق التصريح", "keep": "مدة المشروع + سنتان"}, {"name": "سجل التفتيش المفاجئ للأمن والسلامة", "where": "متابعة التصريح في المنصة", "keep": "5 سنوات"}], "kpis": [{"name": "التصاريح المغلقة في وقتها", "formula": "التصاريح المغلقة خلال ساعتين من نهاية مدتها ÷ التصاريح المغلقة", "target": "≥ 95٪", "freq": "شهري", "source": "نموذج تصريح العمل في المنصة", "auto": "permit_ontime"}, {"name": "الأعمال عالية الخطورة المنفذة بتصريح", "formula": "الأعمال عالية الخطورة بتصريح ÷ الأعمال عالية الخطورة المرصودة في الجولات", "target": "100٪", "freq": "شهري", "source": "جولات الأمن والسلامة"}, {"name": "حوادث مرتبطة بالعزل أو الأعمال الساخنة", "formula": "عدد الحوادث", "target": "صفر", "freq": "شهري", "source": "سجل الحوادث (H-03)"}], "review": "سنوياً، وبعد أي حادث أو حادث وشيك مرتبط بتصريح عمل."}'::jsonb,
  steps = (select jsonb_agg(s.v || coalesce(e.v,'{}'::jsonb) order by s.i)
           from jsonb_array_elements(p.steps) with ordinality s(v,i)
           left join jsonb_array_elements('[{"detail": ["يُرفع الطلب من نموذج «تصريح عمل» في المنصة: نوع العمل، الموقع بدقة، الوقت من/إلى، المنفذ، عدد العاملين، المعدات", "يُرفق تقييم مخاطر مختصر وأسماء العاملين وشهادات المؤهلين (كهربائي، لحام، أماكن محصورة)", "للمقاولين: يُرفق إثبات تهيئة السلامة لعمالتهم (H-07)"], "record": "طلب التصريح"}, {"detail": ["التحقق من أن الضوابط تناسب كل خطر في الطلب (جدول المخاطر في هذا الدليل)", "تحديد نقاط العزل بالاسم والرقم", "تحديد هل يحتاج اعتماد السلامة أو مكافحة العدوى"], "criteria": "يُرفض الطلب أو يُعاد إذا: لم تُحدَّد نقاط العزل، أو لا يوجد مؤهل للعمل، أو تعارض مع إيقاف أو عمل آخر في المنطقة نفسها.", "escalate": "إذا لم يُبَت خلال 4 ساعات يُرفع لرئيس قسم الصيانة."}, {"detail": ["الأعمال الساخنة: التحقق من الطفاية ومراقب الحريق وإزالة المواد القابلة للاشتعال ضمن 11 م", "الأماكن المحصورة: قياس الغازات وخطة الإنقاذ", "تعطيل كواشف أو رشاشات: لا يُعتمد إلا مع تعطيل مسجل حسب H-01"], "criteria": "يُعتمد فقط إذا كانت كل الضوابط متاحة فعلاً في الموقع قبل البدء.", "record": "اعتماد السلامة على التصريح"}, {"detail": ["تحديد فئة الحماية حسب ICRA (نوع العمل × مجموعة خطورة المنطقة)", "تحديد الحواجز والضغط السالب ومسار المخلفات"], "criteria": "الفئات العليا (III–IV) لا يبدأ العمل فيها إلا بعد تفتيش الحواجز.", "record": "نموذج ICRA"}, {"detail": ["لا يُستثنى مقاول مشروع من التصريح", "مهندس المشروع يتابع إغلاق تصاريح مقاوليه يومياً"]}, {"detail": ["قفل شخصي وبطاقة لكل عامل على كل نقطة عزل", "التحقق بجهاز قياس من انعدام الجهد أو الضغط", "تسجيل نقاط العزل وأسماء واضعي الأقفال"], "record": "سجل العزل والأقفال"}, {"detail": ["التصريح معلق في الموقع ظاهراً طوال العمل", "أي تغير في النطاق أو الظروف يوقف العمل ويستلزم تصريحاً جديداً"], "escalate": "أي حادث أو حادث وشيك يُبلَّغ فوراً للأمن والسلامة (H-03)."}, {"detail": ["تفتيش واحد على الأقل لكل تصريح عالي الخطورة", "تسجيل المخالفات ومن أُوقف عمله"], "criteria": "يُوقف العمل فوراً عند خطر وشيك، أو غياب التصريح، أو غياب مراقب الحريق.", "record": "سجل التفتيش"}, {"detail": ["البقاء في الموقع 30 دقيقة على الأقل بعد آخر شرارة", "فحص ما خلف الجدران والأسقف المجاورة"]}, {"detail": ["يزيل كل عامل قفله بنفسه بعد خروجه", "اختبار تشغيل المعدة بحضور المنفذ"]}, {"detail": ["توقيع المنفذ والمُصدر على الإغلاق", "تأكيد قائمة الإغلاق في المنصة (إزالة العزل، تنظيف الموقع، إعادة الأنظمة)"], "record": "التصريح المغلق", "escalate": "التصريح غير المغلق بعد ساعتين من نهايته يظهر متأخراً لرئيس قسم الصيانة."}]'::jsonb) with ordinality e(v,i) using (i)),
  version = '2.0'
where p.code = 'M-01' and p.doc = '{}'::jsonb and jsonb_array_length(p.steps) = 11;

update public.gov_processes p set
  doc = '{"purpose": "ضمان ألا تبقى أي منطقة مشغولة دون حماية من الحريق إلا بإجراءات سلامة بديلة (ILSM) معلنة ومراقبة، وأن يُسجَّل كل تعطيل ويُعاد النظام ويُختبر في أقصر وقت.", "scope": "أي تعطيل كلي أو جزئي، مخطط أو طارئ، لأنظمة: الإنذار من الحريق، الرشاشات، مضخات الحريق، صناديق الحريق وخطوط الإطفاء، الإطفاء بالغاز، أبواب ومخمدات الحريق، ومخارج الطوارئ وممراتها.", "out_of_scope": "إيقاف كاشف واحد لثوانٍ أثناء الاختبار الدوري بحضور فني الاختبار (يُسجَّل في سجل الاختبار لا هنا).", "definitions": [{"t": "التعطيل (Impairment)", "d": "أي حالة تمنع نظام حماية من الحريق من أداء وظيفته كلياً أو جزئياً."}, {"t": "الإجراءات البديلة (ILSM)", "d": "إجراءات سلامة مؤقتة تعوّض النظام المعطل: دوريات مراقبة، طفايات إضافية، منع الأعمال الساخنة، إبلاغ، تدريب."}, {"t": "منسق التعطيل", "d": "مسؤول الأمن والسلامة المكلّف بفتح سجل التعطيل ومتابعته حتى الإغلاق."}], "roles": [{"role": "الأمن والسلامة", "resp": "مالك الإجراء؛ يسجّل التعطيل، يقيّم الأثر، يفعّل الإجراءات البديلة، يبلّغ، ويغلق السجل بعد الاختبار."}, {"role": "الصيانة", "resp": "تبلّغ فوراً بأي عطل، تُصلح، وتختبر النظام وتعيد ربطه."}, {"role": "إدارة المنشأة والأقسام المتأثرة", "resp": "توعية العاملين، تقليل مصادر الاشتعال، تنفيذ ما يُطلب من الإجراءات البديلة."}, {"role": "المرافق", "resp": "تحديث حالة المساحة في سجل المواقع."}, {"role": "مدير الإدارة", "resp": "مراجعة شهرية للتعطيلات المتكررة وتوجيه الإصلاح أو الإحلال."}], "refs": [{"std": "سباهي — معايير المنشآت الصحية، فصل إدارة المرافق والسلامة (FMS)", "title": "السلامة من الحريق وأنظمة الحماية، وإجراءات السلامة البديلة"}, {"std": "NFPA 25 — الفصل 15", "title": "إجراءات تعطيل أنظمة الإطفاء بالمياه"}, {"std": "NFPA 72", "title": "الإنذار من الحريق — الصيانة والاختبار والتعطيل"}, {"std": "NFPA 101", "title": "كود سلامة الأرواح — المخارج وممراتها"}, {"std": "SBC 801", "title": "كود الحماية من الحريق السعودي"}], "risks": [{"risk": "حريق في منطقة بلا كشف أو إطفاء", "control": "دوريات مراقبة حريق موثقة كل ساعة على الأقل، طفايات إضافية، منع الأعمال الساخنة."}, {"risk": "نسيان النظام معطلاً بعد انتهاء العمل", "control": "سجل التعطيل مفتوح في المنصة بموعد إعادة يظهر متأخراً، ولا يُغلق إلا باختبار موثق."}, {"risk": "إشغال المخارج بمواد العمل", "control": "تفتيش يومي للممرات، ووضع مسارات بديلة معلنة."}], "exceptions": [{"case": "تعطيل طارئ يهدد السلامة", "action": "يُعامل طوارئ (G-11) بالتوازي، وتُفعَّل الإجراءات البديلة فوراً دون انتظار التقييم."}, {"case": "تعطيل خارج الدوام", "action": "يبلغ الفني المناوب الأمن والسلامة المناوب هاتفياً، ويُفتح السجل في المنصة في الوقت نفسه."}], "records": [{"name": "سجل التعطيل (نموذج «تعطيل أنظمة الحريق» في المنصة)", "where": "البلاغات والطلبات ← تعطيل أنظمة الحريق", "keep": "5 سنوات"}, {"name": "سجل دوريات المراقبة", "where": "مرفق سجل التعطيل", "keep": "5 سنوات"}, {"name": "محضر اختبار النظام بعد الإعادة", "where": "مرفق سجل التعطيل", "keep": "5 سنوات"}], "kpis": [{"name": "عودة النظام في الموعد المعلن", "formula": "التعطيلات المغلقة قبل موعد الإعادة المعلن ÷ التعطيلات المغلقة", "target": "≥ 95٪", "freq": "شهري", "source": "نموذج تعطيل أنظمة الحريق", "auto": "impair_ontime"}, {"name": "التعطيلات المفتوحة الآن", "formula": "عدد سجلات التعطيل غير المغلقة", "target": "أقل ما يمكن، ولا تعطيل متأخر", "freq": "لحظي", "source": "المنصة", "auto": "impair_open"}, {"name": "التعطيلات غير المسجلة", "formula": "تعطيلات اكتُشفت في الجولات دون سجل", "target": "صفر", "freq": "شهري", "source": "جولات الأمن والسلامة"}], "review": "سنوياً، وبعد أي حريق أو تعطيل تجاوز 24 ساعة."}'::jsonb,
  steps = (select jsonb_agg(s.v || coalesce(e.v,'{}'::jsonb) order by s.i)
           from jsonb_array_elements(p.steps) with ordinality s(v,i)
