"}], "records": [{"name": "الخطط الدورية", "where": "قسم الصيانة ← الأعمال المخططة", "keep": "مدة خدمة الأصل"}, {"name": "أوامر PPM المنفذة بقوائم التحقق والنتيجة", "where": "الأعمال", "keep": "مدة خدمة الأصل"}, {"name": "تقرير الإنجاز الشهري", "where": "التقرير الشهري للإدارة", "keep": "5 سنوات"}], "kpis": [{"name": "نسبة إنجاز PPM الشهرية", "formula": "أوامر PPM المستحقة هذا الشهر والمنجزة ÷ أوامر PPM المستحقة هذا الشهر", "target": "≥ 90٪", "freq": "شهري", "source": "الأعمال المخططة في المنصة", "auto": "ppm_month"}, {"name": "أوامر PPM المتأخرة الآن", "formula": "أوامر PPM مفتوحة تجاوزت موعدها", "target": "صفر", "freq": "لحظي", "source": "المنصة", "auto": "ppm_late"}, {"name": "نتائج غير مطابقة", "formula": "أوامر PPM بنتيجة «غير مطابق» ÷ المنفذة", "target": "تنخفض ربعياً", "freq": "ربع سنوي", "source": "المنصة"}], "review": "سنوياً عند بناء الخطة الجديدة."}'::jsonb,
