update public.gov_processes p set
  doc = '{"purpose": "انتقال منظّم وموثق للمشروع من قسم المشاريع إلى الأقسام المشغّلة، بحيث يبدأ التشغيل بأنظمة مختبرة، وسجل أصول محدّث، وخطط صيانة جاهزة، وضمانات موثقة، ودون ملاحظات مفتوحة تمس السلامة.", "scope": "جميع مشاريع التأهيل والإنشاء التي تسلّم مساحات أو أنظمة لمنشآت التجمع، من إشعار المقاول بالجاهزية حتى تشغيل المنشأة للمساحة.", "out_of_scope": "الاستلام النهائي بعد الضمان (P-14).", "definitions": [{"t": "الاستلام الابتدائي", "d": "استلام الأعمال المكتملة مع قائمة ملاحظات بمهلة إنهاء، ويبدأ منه الضمان."}, {"t": "ملف التسليم", "d": "المخططات كما نُفّذ، الضمانات، كتيبات التشغيل والصيانة، شهادات الاختبار، قائمة الأصول وقطع الغيار."}, {"t": "لجنة الاستلام", "d": "ممثلو المشاريع والمرافق والصيانة والأمن والسلامة، ومن يلزم من تقنية المعلومات والصيانة الطبية والمنشأة."}], "roles": [{"role": "المشاريع", "resp": "مالك الإجراء؛ يتحقق من الاكتمال، يدعو اللجنة، يُصدر المحضر، ويستلم ملف التسليم."}, {"role": "الصيانة", "resp": "فحص الأنظمة الكهروميكانيكية، وإدراج الأصول في PPM."}, {"role": "الأمن والسلامة", "resp": "فحص السلامة من الحريق واشتراطات الدفاع المدني (قرار إيقاف التشغيل بيده)."}, {"role": "تقنية المعلومات والصيانة الطبية", "resp": "فحص الشبكات والأنظمة ومواقع الأجهزة الطبية."}, {"role": "المرافق", "resp": "تحديث سجل الأصول والمواقع والمخططات."}, {"role": "الخدمات العامة والمنشأة", "resp": "التنظيف النهائي، واستلام الموقع للتشغيل وتقييم الخدمة."}], "refs": [{"std": "سباهي — معايير المنشآت الصحية، فصل إدارة المرافق والسلامة (FMS)", "title": "استلام وتشغيل المساحات الجديدة وسجل الأصول وخطط الصيانة"}, {"std": "SBC 801 واشتراطات الدفاع المدني", "title": "فحص السلامة قبل الإشغال"}, {"std": "عقد المشروع", "title": "شروط الاستلام والضمان والغرامات"}], "risks": [{"risk": "تشغيل مساحة بعيب سلامة", "control": "فحص السلامة قرار إلزامي قبل المحضر (R-23)؛ الملاحظة الحرجة توقف التشغيل."}, {"risk": "ضياع الضمانات والكتيبات", "control": "ملف التسليم شرط لصرف الدفعة الختامية، ويُرفع في مستندات المشروع."}, {"risk": "أصول جديدة خارج الصيانة", "control": "إدراجها في خطط PPM خلال أسبوع وبدء الضمان مسجل."}], "exceptions": [{"case": "حاجة تشغيلية عاجلة قبل اكتمال الملاحظات", "action": "تشغيل جزئي بقرار مكتوب من مدير الإدارة بعد خلو الملاحظات الحرجة، مع مهلة للباقي."}], "records": [{"name": "محضر الاستلام الابتدائي بالملاحظات ومهلها", "where": "المستندات الرسمية للمشروع", "keep": "مدة المشروع + 10 سنوات"}, {"name": "ملف التسليم (As-built، ضمانات، O&M، اختبارات)", "where": "مستندات المشروع", "keep": "عمر المبنى"}, {"name": "نموذج «تسليم مشروع للتشغيل» بقائمة التحقق", "where": "البلاغات والطلبات", "keep": "5 سنوات"}], "kpis": [{"name": "اكتمال ملف التسليم خلال أسبوعين", "formula": "التسليمات المغلقة خلال 14 يوماً من فتحها ÷ التسليمات المغلقة", "target": "≥ 90٪", "freq": "ربع سنوي", "source": "نموذج تسليم مشروع للتشغيل", "auto": "handover_2w"}, {"name": "ملاحظات مفتوحة عند بدء التشغيل", "formula": "ملاحظات حرجة مفتوحة يوم التشغيل", "target": "صفر", "freq": "لكل مشروع", "source": "محضر الاستلام"}], "review": "سنوياً، وبعد أي تشغيل تعثّر بسبب نقص في التسليم."}'::jsonb,
  steps = (select jsonb_agg(s.v || coalesce(e.v,'{}'::jsonb) order by s.i)
           from jsonb_array_elements(p.steps) with ordinality s(v,i)
           left join jsonb_array_elements('[{"detail": ["مراجعة نتائج الاختبارات والتشغيل لكل نظام", "قائمة إغلاق المشروع (P-13)"]}, {"detail": ["دعوة مكتوبة بالموعد والنطاق وقائمة الأنظمة"]}, {"detail": ["تشغيل فعلي لكل نظام وتسجيل الملاحظات بالصور"]}, {"detail": ["شهادات اختبار الكابلات والألياف"]}, {"detail": ["التحقق من التغذيات والغازات ومواقع التثبيت"]}, {"detail": ["المخارج والإنذار والإطفاء وأبواب الحريق واللوحات"], "criteria": "أي ملاحظة حرجة في السلامة تمنع التشغيل حتى إغلاقها."}, {"record": "محضر الاستلام الابتدائي"}, {"detail": ["مخططات كما نُفّذ، ضمانات، كتيبات، جداول PPM، قائمة الأصول وقطع الغيار"], "record": "ملف التسليم", "escalate": "تأخر الملف عن أسبوعين يُرفع لرئيس قسم المشاريع ويُربط بصرف الدفعة."}, {"record": "سجل الأصول المحدّث"}, {"detail": ["إنشاء الخطط الدورية للأصول الجديدة", "تسجيل تاريخ بدء الضمان ونهايته"]}, {}, {"detail": ["تقييم المنشأة للتسليم والتشغيل"]}]'::jsonb) with ordinality e(v,i) using (i)),
  version = '2.0'
where p.code = 'G-04' and p.doc = '{}'::jsonb and jsonb_array_length(p.steps) = 12;

update public.gov_processes p set
  doc = '{"purpose": "ضمان أن كل سيارة تخرج من المقر مسجلة باسم مستلمها وغرضها ووجهتها وعدادها ووقودها وحالتها، وتعود في اليوم نفسه، وأن أي ضرر يُكتشف ويُنسب ويُعالَج فوراً.", "scope": "سيارات أسطول المقر الرئيسي لإدارة الخدمات الفنية حين يستلمها موظفو الأقسام لمهام العمل اليومية.", "out_of_scope": "المهام الطويلة والمبيت وخارج المحافظة (V-06)، والحوادث والمخالفات (V-05)، والصيانة (V-03).", "definitions": [{"t": "الرحلة", "d": "فترة استخدام سيارة من التسليم حتى الاستلام، برقم TRP في المنصة."}, {"t": "محضر التسليم والاستلام", "d": "سجل الرحلة: العداد والوقود وقائمة الفحص عند الطرفين، والضرر إن وُجد، قابل للطباعة بتوقيعين."}, {"t": "مسؤول الحركة", "d": "موظف قسم الحركة المكلّف بالتسليم والاستلام."}], "roles": [{"role": "قسم الحركة", "resp": "مالك الإجراء؛ يخصص السيارة، يسلّم ويستلم بمحضر، يتابع المتأخر."}, {"role": "الموظف المستلم", "resp": "يطلب مسبقاً، يستخدم السيارة للمهمة فقط، يعيدها في وقتها، ويبلغ فوراً عن أي حادث أو عطل."}, {"role": "مدير الإدارة", "resp": "يُبلَّغ بالتأخر المتكرر والأضرار، ويعتمد المبيت الطويل."}], "refs": [{"std": "نظام المرور السعودي ولائحته", "title": "الرخصة السارية والمخالفات"}, {"std": "سياسات التجمع لاستخدام سيارات الجهة", "title": "استخدام السيارة للمهام الرسمية فقط"}, {"std": "القواعد R-37..R-41", "title": "قواعد الحركة في هذا الدليل"}], "risks": [{"risk": "ضرر لا يُعرف متسببه", "control": "قائمة فحص وصور عند التسليم والاستلام، والضرر غير الموثق عند التسليم يُسأل عنه آخر مستلم (R-39)."}, {"risk": "سيارة لا تعود", "control": "موعد عودة افتراضي 3:30 م، وتنبيه تلقائي للمستلم والقسم عند التأخر."}, {"risk": "تسليم سيارة بوثيقة منتهية", "control": "المنصة تمنع التسليم تلقائياً (R-41)."}], "exceptions": [{"case": "حاجة عاجلة دون طلب مسبق", "action": "يُسجَّل التسليم المباشر في لوحة الحركة باسم الموظف الحاضر."}, {"case": "تأخر لظرف المهمة", "action": "يطلب الموظف تمديداً قبل الموعد، ويسجّله مسؤول الحركة."}], "records": [{"name": "الرحلة بمحضرها وصورها", "where": "لوحة الحركة / سجل الحركة", "keep": "5 سنوات (للرجوع في المخالفات)"}, {"name": "بلاغ الضرر التلقائي", "where": "البلاغات (عطل سيارة)", "keep": "عمر السيارة"}], "kpis": [{"name": "العودة في الموعد", "formula": "الرحلات المعادة خلال 15 دقيقة من موعدها ÷ الرحلات المعادة", "target": "≥ 95٪", "freq": "شهري", "source": "سجل الحركة", "auto": "trips_ontime"}, {"name": "السيارات المتأخرة الآن", "formula": "رحلات خارج المقر تجاوزت موعد العودة", "target": "صفر", "freq": "لحظي", "source": "لوحة الحركة", "auto": "trips_late"}], "review": "سنوياً، وعند تغيّر حجم الأسطول."}'::jsonb,
  steps = (select jsonb_agg(s.v || coalesce(e.v,'{}'::jsonb) order by s.i)
           from jsonb_array_elements(p.steps) with ordinality s(v,i)
           left join jsonb_array_elements('[{"detail": ["من «سيارات المقر» ← طلب سيارة: الغرض، الوجهة، وقت الخروج والعودة، المرافقون، الجوال"]}, {"criteria": "تُخصَّص سيارة متاحة وثائقها سارية؛ المبيت أو العودة في يوم آخر يتبع V-06؛ يُرفض الطلب بسبب مكتوب إذا لم تتوفر سيارة."}, {"detail": ["تسجيل العداد ومستوى الوقود وقائمة الفحص", "الاطلاع على الرخصة السارية", "صور للسيارة عند الحاجة"], "record": "محضر التسليم"}, {"escalate": "الحادث أو العطل يُبلَّغ فوراً لقسم الحركة ويُرفع «حادث أو مخالفة مرورية» (V-05)."}, {"detail": ["العداد والوقود والتعبئة وقائمة الفحص", "ملاحظات الاستلام"], "record": "محضر الاستلام"}, {"criteria": "أي ضرر أو عطل: السيارة «في الصيانة» وبلاغ عطل تلقائي (V-03) مع الصور."}, {"detail": ["التنبيه التلقائي 3:30 م", "التقرير الشهري: الرحلات، الكيلومترات، العودة في الموعد، الاستخدام حسب القسم"]}]'::jsonb) with ordinality e(v,i) using (i)),
  version = '2.0'
where p.code = 'V-01' and p.doc = '{}'::jsonb and jsonb_array_length(p.steps) = 7;
